CREATE TABLE charges ( id VARCHAR(40) PRIMARY KEY, merchant_id VARCHAR(40) NOT NULL, idempotency_key VARCHAR(80) NOT NULL, amount_minor BIGINT NOT NULL, -- cents, NEVER float currency CHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, -- pending|captured|failed|refunded psp_charge_id VARCHAR(60), created_at TIMESTAMPTZ NOT NULL, UNIQUE (merchant_id, idempotency_key)
); CREATE TABLE ledger_entries ( id BIGSERIAL PRIMARY KEY, charge_id VARCHAR(40) REFERENCES charges(id), account_id VARCHAR(40) NOT NULL, direction CHAR(1) NOT NULL, -- 'D' debit or 'C' credit amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, posted_at TIMESTAMPTZ NOT NULL
);
```

